    if (str == null) {
        throw new IllegalArgumentException("Input CharSequence is null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("Invalid index or length");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (ch <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

